def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    comps = components(g != bg, diagonal=True)
    moves = []
    for cells in comps:
        cs = set(cells)
        centre = None
        for (y, x) in cells:
            if all((y+dy, x+dx) in cs for dy, dx in ((1,0),(-1,0),(0,1),(0,-1))):
                centre = (y, x); break
        if centre is None:
            continue
        ones = [(y, x) for (y, x) in cells if g[y, x] == 1]
        my = np.mean([p[0] for p in ones]); mx = np.mean([p[1] for p in ones])
        dy = int(np.sign(round(centre[0] - my))); dx = int(np.sign(round(centre[1] - mx)))
        cy, cx = centre
        if dy > 0: s = (H - 1) - (cy + 1)
        elif dy < 0: s = cy - 1
        elif dx > 0: s = (W - 1) - (cx + 1)
        else: s = cx - 1
        moves.append((cells, centre, dy, dx, s))
    for cells, (cy, cx), dy, dx, s in moves:
        for (y, x) in cells:
            out[y, x] = bg
    for cells, (cy, cx), dy, dx, s in moves:
        oy, ox = dy * s, dx * s
        head = {(cy+a, cx+b) for a, b in ((0,0),(1,0),(-1,0),(0,1),(0,-1))}
        for (y, x) in cells:
            if (y, x) in head:
                ny, nx = 2*cy - y + oy, 2*cx - x + ox  # 180° rotation about centre, then shift
            else:
                ny, nx = y + oy, x + ox
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = g[y, x]
        emit(out.copy(), f"Rocket at centre ({cy},{cx}) flies {s} cells toward its head until it touches the border; its plus head is rotated 180 degrees.")
    emit(out, "All rockets moved to the border: final grid.")
    return out
